// Triplica a lista para o loop de CSS (translateX -33.333%) ficar contínuo
// sem "salto" visível entre o fim e o início.
const marqueeItems = [...STACK, ...STACK, ...STACK]

const { theme } = useTheme()

function iconColor(tech: TechIcon): string | undefined {
  if (!tech.hex) return undefined
  const hex = theme.value === 'light' && tech.lightHex ? tech.lightHex : tech.hex
  return `#${hex}`
}
</script>

<template>
  <div
    class="mask-[linear-gradient(to_right,transparent_0%,black_15%,black_85%,transparent_100%)] w-full overflow-hidden"
  >
    <div class="tech-marquee-track flex w-max gap-3 py-1">
      <span
        v-for="(tech, index) in marqueeItems"
        :key="`${tech.title}-${index}`"
        class="flex shrink-0 items-center gap-1.5 rounded-full border bg-secondary px-3 py-1.5 text-xs font-medium text-secondary-foreground transition-colors hover:text-foreground"
      >
        <svg
          viewBox="0 0 24 24"
          class="size-3.5 shrink-0"
          :style="{ color: iconColor(tech) }"
          aria-hidden="true"
        >
          <path :d="tech.path" fill="currentColor" />
        </svg>
        {{ tech.title }}
      </span>
    </div>
  </div>
</template>

<style scoped>
.tech-marquee-track {
  animation: tech-marquee 40s linear infinite;
}

@keyframes tech-marquee {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-33.3333%);
  }
}

@media (prefers-reduced-motion: reduce) {
  .tech-marquee-track {
    animation: none;
  }
}
</style>
